"""The context of a page is regenerated by every build (ADR 014 decision 9).

The tests build small websites with Quarto: once from sources (the base), then
a run that restores the store of the lessons it did not change and executes the
others. Every scenario also builds the same tree in full and requires the
two sites to be byte-identical, so a page taken from the store is the page that
a full build writes: the navigation of this tree and the commit of this run.
"""

import json
import re
import shutil
from pathlib import Path

import pytest
from support.checks import output, run_check

from pbc.authoring import selection as selecting
from pbc.authoring.context import (
    InvalidContext,
    marker,
    regenerate,
    regenerate_page,
)
from pbc.authoring.repository import BuildCommit

REPOSITORY = "https://github.com/example/project"
BASE_COMMIT = BuildCommit("a" * 40, False)
RUN_COMMIT = BuildCommit("b" * 40, False)
CONFIG = """\
project:
  type: website
format:
  html:
    html-math-method: mathml
"""
REAL_SITE = Path(__file__).parents[2] / "site"
STORE = (REAL_SITE / "_quarto-store.yml").read_text()

CELLS = """\
```{python}
#| label: header
#| echo: false
from pbc.authoring import lesson_header

lesson_header()
```

Text of the lesson.

```{python}
#| label: log
#| echo: false
import os
with open(os.environ['PBC_TEST_LOG'], 'a') as log:
    log.write('%(id)s\\n')
```

## Run this experiment {#reproduce-this}

```{python}
#| label: reproduce
#| echo: false
from pbc.authoring import reproduce_this

reproduce_this(code=[], tests=[])
```
"""

PATH_PAGE = """\
---
title: "Learning path"
---

```{python}
#| label: path
#| echo: false
#| output: asis
from pbc.authoring import learning_path
from pbc.authoring.atlas import course_atlas

# As site/path/index.qmd: the sequences list the lessons (F133).
print(course_atlas())
print(learning_path())
```
"""


def lesson_text(
    id: str,
    strand: str = "mechanics",
    order: int = 1,
    title: str | None = None,
    prerequisites: tuple[str, ...] = (),
    related: tuple[str, ...] = (),
) -> str:
    method = {"mechanics": "simulation", "agents-llm": "llm-agents", "lean": "lean"}
    experiment = {
        "mechanics": "pbc.mechanics.experiments.kinematics",
        "agents-llm": "pbc.mechanics.experiments.agent_experiment",
        "lean": "./scripts/check-lean.sh",
    }
    return (
        f'---\ntitle: "{title or id.upper()}"\n'
        f"lesson:\n  id: {id}\n  strand: {strand}\n  order: {order}\n"
        f"  difficulty: 1\n  course: mechanics\n  methods: [{method[strand]}]\n"
        f"  experiment: {experiment[strand]}\n"
        '  outcomes:\n    - "Do the first thing"\n    - "Do the second thing"\n'
        f"  related: [{', '.join(related)}]\n"
        f"  prerequisites:\n    lessons: [{', '.join(prerequisites)}]\n"
        "    outside: []\n---\n\n" + CELLS % {"id": id}
    )


# The lessons of the base: A and B in mechanics, C in lean.
LESSONS = {
    "a": dict(strand="mechanics", order=1, related=("b",)),
    "b": dict(strand="mechanics", order=2),
    "c": dict(strand="lean", order=1, prerequisites=("b",)),
}
DIRECTORY = {"a": "01-a", "b": "02-b", "c": "01-c", "x": "01-x"}


def directory(id: str, strand: str) -> str:
    return f"lessons/{strand}/{DIRECTORY[id]}"


def write(site: Path, name: str, text: str) -> None:
    (site / name).parent.mkdir(parents=True, exist_ok=True)
    (site / name).write_text(text, encoding="utf-8")


def put(site: Path, id: str, **changes) -> None:
    facts = {**LESSONS.get(id, {}), **changes}
    write(site, f"{directory(id, facts['strand'])}/index.qmd", lesson_text(id, **facts))


def write_site(site: Path) -> None:
    # What the conversion of a region reads from the site.
    for name in ("assets/lean.xml", "_filters/scroll-regions.lua"):
        write(site, name, (REAL_SITE / name).read_text())
    write(site, "_quarto.yml", CONFIG)
    write(site, "_quarto-store.yml", STORE)
    write(site, "glossary.yaml", "entries: []\n")
    write(site, "path/index.qmd", PATH_PAGE)
    for id in LESSONS:
        put(site, id)


def build(site: Path, out: Path, log: Path, commit: BuildCommit, chosen=None) -> None:
    env = {"PBC_TEST_LOG": str(log)}
    if chosen is not None:
        env["PBC_STORE_SELECTION"] = str(chosen)
    result = run_check("site-build", site, out, env=env)
    assert result.returncode == 0, output(result)
    # What the post-render step of the site does, with the commit of this run.
    regenerate(out, site, commit, REPOSITORY)


def selection(path: Path, base: Path, execute: list[str], reuse: list[str]) -> Path:
    path.write_text(
        json.dumps(
            {
                "format": selecting.SELECTION_FORMAT,
                "mode": "selective",
                "reason": "",
                "base": {"id": "x", "identity": "y"},
                "base_directory": str(base),
                "lessons": sorted(execute + reuse),
                "execute": execute,
                "reuse": reuse,
            }
        )
    )
    return path


def lesson_dir(id: str, strand: str) -> str:
    return f"site/{directory(id, strand)}"


def html(out: Path, id: str, strand: str) -> str:
    return (out / directory(id, strand) / "index.html").read_text()


def fact(page: str, term: str) -> str:
    """The text of the definition of ``term`` in the header of ``page``."""
    found = re.search(rf"<dt>{term}</dt>\s*<dd>(.*?)</dd>", page, re.S)
    assert found, f"the header has no {term}"
    return " ".join(found.group(1).split())


def linked_titles(text: str) -> list[str]:
    return re.findall(r">([^<]+)</a>", text)


class Run:
    """The base of the lessons above, and runs against it."""

    def __init__(self, root: Path):
        self.root = root
        self.site = root / "site"
        self.log = root / "log"
        self.base = root / "base"

    @classmethod
    def made(cls, root: Path) -> Run:
        run = cls(root)
        write_site(run.site)
        build(run.site, root / "base-site", run.log, BASE_COMMIT)
        shutil.copytree(run.site / "_freeze", run.base / "freeze")
        run.log.unlink()
        return run

    def against_base(
        self, execute: list[tuple[str, str]], reuse: list[tuple[str, str]]
    ):
        """Build this tree restoring ``reuse`` from the base, then build it in
        full, and require the two sites to be the same."""
        chosen = selection(
            self.root / "selection.json",
            self.base,
            [lesson_dir(*item) for item in execute],
            [lesson_dir(*item) for item in reuse],
        )
        out = self.root / "out"
        build(self.site, out, self.log, RUN_COMMIT, chosen)
        executed = sorted(self.log.read_text().split())
        self.log.unlink()
        full = self.root / "full"
        shutil.copytree(
            self.site, self.root / "full-site", ignore=shutil.ignore_patterns("_freeze")
        )
        build(self.root / "full-site", full, self.log, RUN_COMMIT)
        self.log.unlink()
        self.executed = executed
        self.compare(out, full)
        return out

    @staticmethod
    def compare(out: Path, full: Path) -> None:
        names = sorted(
            p.relative_to(full).as_posix() for p in full.rglob("*") if p.is_file()
        )
        assert names == sorted(
            p.relative_to(out).as_posix() for p in out.rglob("*") if p.is_file()
        )
        differing = [
            n for n in names if (out / n).read_bytes() != (full / n).read_bytes()
        ]
        assert not differing, f"a run with a base differs from a full run: {differing}"


@pytest.fixture(scope="module")
def made(tmp_path_factory) -> Path:
    root = tmp_path_factory.mktemp("context")
    Run.made(root)
    return root


@pytest.fixture
def run(made: Path, tmp_path: Path) -> Run:
    shutil.copytree(made, tmp_path / "run", symlinks=True)
    return Run(tmp_path / "run")


def test_the_base_shows_its_own_neighbours_and_commit(made: Path):
    page = html(made / "base-site", "b", "mechanics")

    assert linked_titles(fact(page, "Previous")) == ["A"]
    assert linked_titles(fact(page, "Next")) == ["C"]
    assert BASE_COMMIT.sha in page
    assert "pbc-context" not in page


def test_inserting_a_lesson_updates_the_neighbours_that_did_not_change(run: Run):
    put(run.site, "x", strand="agents-llm", order=1)
    mechanics = lambda id: (id, "mechanics")  # noqa: E731

    out = run.against_base(
        execute=[("x", "agents-llm")],
        reuse=[mechanics("a"), mechanics("b"), ("c", "lean")],
    )

    assert run.executed == ["x"]
    # B was followed by C and is now followed by X; C was preceded by B.
    assert linked_titles(fact(html(out, "b", "mechanics"), "Next")) == ["X"]
    assert linked_titles(fact(html(out, "c", "lean"), "Previous")) == ["X"]
    assert linked_titles(fact(html(out, "a", "mechanics"), "Next")) == ["B"]
    path = (out / "path" / "index.html").read_text()
    assert "X" in re.findall(r">([^<]+)</a>", path)
    assert "lesson 1 of" in html(out, "a", "mechanics")


def test_retitling_a_lesson_updates_every_unchanged_page_that_links_to_it(run: Run):
    put(run.site, "b", title="Beta")

    out = run.against_base(
        execute=[("b", "mechanics")],
        reuse=[("a", "mechanics"), ("c", "lean")],
    )

    assert run.executed == ["b"]
    first, last = html(out, "a", "mechanics"), html(out, "c", "lean")
    assert linked_titles(fact(first, "Next")) == ["Beta"]
    assert linked_titles(fact(first, "Related")) == ["Beta"]
    assert linked_titles(fact(last, "Previous")) == ["Beta"]
    assert linked_titles(fact(last, "Prerequisites")) == ["Beta"]
    assert "Beta" in (out / "path" / "index.html").read_text()


def test_a_prerequisite_or_related_link_of_a_changed_lesson_changes_what_shows_it(
    run: Run,
):
    put(run.site, "b", prerequisites=("a",), related=("c",))

    out = run.against_base(
        execute=[("b", "mechanics")],
        reuse=[("a", "mechanics"), ("c", "lean")],
    )

    page = html(out, "b", "mechanics")
    assert linked_titles(fact(page, "Prerequisites")) == ["A"]
    assert linked_titles(fact(page, "Related")) == ["C"]
    # A and C show nothing of it: they are the pages of the base with the
    # commit of this run (the comparison with the full run above shows it).
    assert run.executed == ["b"]
    for id, strand in (("a", "mechanics"), ("c", "lean")):
        assert BASE_COMMIT.sha not in html(out, id, strand)


def test_every_page_names_the_commit_of_the_run_and_never_that_of_the_base(run: Run):
    put(run.site, "b", title="Beta")

    out = run.against_base(
        execute=[("b", "mechanics")],
        reuse=[("a", "mechanics"), ("c", "lean")],
    )

    for page in sorted(out.rglob("*.html")):
        text = page.read_text()
        assert BASE_COMMIT.sha not in text, page
    for id, strand in (("a", "mechanics"), ("b", "mechanics"), ("c", "lean")):
        text = html(out, id, strand)
        assert f"{REPOSITORY}/tree/{RUN_COMMIT.sha}" in text
        # The section ends in the experiment of the lesson, never in a render.
        shown = re.sub(r"<[^>]+>", "", text)
        if strand == "lean":
            assert "lake build" in shown
        else:
            assert "python -m pbc.mechanics.experiments.kinematics results" in shown
        assert "quarto render" not in shown
        # The page that is restored from the store was not executed.
    assert run.executed == ["b"]


# --- The markers ---------------------------------------------------------------


def site_with_a_lesson(tmp_path: Path) -> Path:
    site = tmp_path / "site"
    write_site(site)
    return site


def region(kind: str = "header", page: str = "lessons/mechanics/02-b/index.qmd"):
    """A built page with the marker of one region, as pandoc writes it."""
    payload = {
        "page": f"site/{page}",
        "code": [],
        "tests": [],
        "experiment": "pbc.mechanics.experiments.kinematics",
        "kind": "run",
        "lean_modules": [],
        "live": "",
    }
    text = marker(kind, page, payload if kind == "reproduce" else {})
    attributes = re.search(r"\{\.pbc-context ([^}]*)\}", text).group(1)
    data = re.sub(r"pbc-", "data-pbc-", attributes)
    return f'<div class="pbc-context" {data}>\n</div>'


def test_a_marker_is_the_same_on_every_build_and_names_no_commit():
    first = marker("excerpt", "lessons/s/01-a/index.qmd", {"a": 1, "b": [2]})
    again = marker("excerpt", "lessons/s/01-a/index.qmd", {"b": [2], "a": 1})

    assert first == again
    assert not re.search(r"[0-9a-f]{40}", first)


def test_a_marker_of_an_unknown_kind_cannot_be_made():
    with pytest.raises(ValueError, match="unknown kind"):
        marker("footer", "x.qmd", {})


@pytest.mark.parametrize(
    ("damage", "message"),
    [
        (
            lambda text: text.replace('data-pbc-kind="header"', 'data-pbc-kind="x"'),
            "unknown kind",
        ),
        (
            lambda text: text.replace("data-pbc-check=", 'data-pbc-check="0" data-x='),
            "checksum",
        ),
        (
            lambda text: text.replace(
                "lessons/mechanics/02-b", "lessons/mechanics/01-a"
            ),
            "made for",
        ),
        (
            lambda text: re.sub(
                r'data-pbc-payload="[^"]*"', 'data-pbc-payload="!"', text
            ),
            "checksum",
        ),
        (lambda text: re.sub(r' data-pbc-check="[^"]*"', "", text), "lacks"),
    ],
    ids=["kind", "checksum", "page", "payload", "missing attribute"],
)
def test_a_marker_that_is_not_valid_fails_the_page(tmp_path: Path, damage, message):
    site = site_with_a_lesson(tmp_path)
    page = "lessons/mechanics/02-b/index.qmd"
    text = f"<main>{damage(region('header', page))}</main>"

    with pytest.raises(InvalidContext, match=message):
        regenerate_page(text, page, site, RUN_COMMIT, REPOSITORY)


def test_a_lesson_page_without_a_header_or_without_a_reproduce_section_fails(
    tmp_path: Path,
):
    site = site_with_a_lesson(tmp_path)
    page = "lessons/mechanics/02-b/index.qmd"

    with pytest.raises(InvalidContext, match="no header region"):
        regenerate_page(region("excerpt", page), page, site, RUN_COMMIT, REPOSITORY)
    with pytest.raises(InvalidContext, match="no reproduce region"):
        regenerate_page(region("header", page), page, site, RUN_COMMIT, REPOSITORY)


def test_a_page_without_a_marker_is_left_as_it_is(tmp_path: Path):
    site = site_with_a_lesson(tmp_path)
    page = "lessons/mechanics/02-b/index.qmd"

    assert regenerate_page("<main></main>", page, site, RUN_COMMIT, REPOSITORY) == (
        "<main></main>"
    )


def test_a_marker_the_pattern_does_not_match_does_not_stay_in_a_page(tmp_path: Path):
    site = site_with_a_lesson(tmp_path)
    page = "lessons/mechanics/02-b/index.qmd"
    text = region("header", page) + region("reproduce", page)
    text += '<div class="pbc-context" onclick="x">'

    with pytest.raises(InvalidContext, match="remains"):
        regenerate_page(text, page, site, RUN_COMMIT, REPOSITORY)


def test_a_page_that_is_not_in_the_site_cannot_carry_a_marker(tmp_path: Path):
    site = site_with_a_lesson(tmp_path)
    output_dir = tmp_path / "out"
    write(output_dir, "orphan.html", region("excerpt", "orphan.qmd"))

    with pytest.raises(InvalidContext, match="without a source"):
        regenerate(output_dir, site, RUN_COMMIT, REPOSITORY)


def test_the_site_regenerates_the_context_before_any_other_post_render_script():
    config = (Path(__file__).parents[2] / "site" / "_quarto.yml").read_text()
    scripts = re.search(r"post-render:\n((?:\s+- .*\n)+)", config).group(1)

    assert scripts.split()[1] == "context.py"


def test_an_excerpt_region_is_rebuilt_for_the_commit_of_the_run(tmp_path: Path):
    """The excerpt of a built page names the file and lines it was read from,
    and the link to them follows the commit of the run, not that of the cell
    that left the marker (#230, m2)."""
    from pbc.authoring.excerpt import excerpt
    from pbc.mechanics import kinematics

    site = site_with_a_lesson(tmp_path)
    page = "extra/index.qmd"
    shown = excerpt(kinematics.euler_step)
    payload = shown.payload()
    cell_output = f"<main>{_html_marker(marker('excerpt', page, payload))}</main>"

    first = regenerate_page(cell_output, page, site, BASE_COMMIT, REPOSITORY)
    second = regenerate_page(cell_output, page, site, RUN_COMMIT, REPOSITORY)

    assert "pbc-context" not in first
    assert "euler_step" in first
    assert payload["path"] in first
    link = f"{REPOSITORY}/blob/{{}}/{payload['path']}#L{payload['first_line']}-L"
    assert link.format(BASE_COMMIT.sha) in first
    assert link.format(RUN_COMMIT.sha) in second
    assert BASE_COMMIT.sha not in second


def _html_marker(text: str) -> str:
    """The marker as pandoc writes it into the built page."""
    attributes = re.search(r"\{\.pbc-context ([^}]*)\}", text).group(1)
    data = re.sub(r"pbc-", "data-pbc-", attributes)
    return f'<div class="pbc-context" {data}>\n</div>'
